# -V:CONFIGVAR: Config.pm keys
_helper_config_keys() {
    perl -MConfig -e 'print "$_\n" for sort keys %Config' 2>/dev/null
}

# List installed perl modules as Foo::Bar names; first @INC occurrence wins.
_helper_scan_modules() {
    _helper_scan_modules_filtered ""
}

# Same as _helper_scan_modules, restricted to names below the Devel:: namespace.
_helper_scan_modules_devel() {
    _helper_scan_modules_filtered "Devel"
}

# Shared module scanner. $1: optional subdirectory filter (e.g. Devel).
_helper_scan_modules_filtered() {
    perl -MFile::Find -e '
        my ($filter, %seen) = (length $ARGV[0] ? $ARGV[0] : undef);
        for my $d (@INC) {
            next unless defined $d && -d $d;
            find({
                wanted => sub {
                    return unless /\.pm$/ && -f $_;
                    my $f = $File::Find::name;
                    $f =~ s/^\Q$d\E\///;
                    $f =~ s/\.pm$//;
                    $f =~ s/\//::/g;
                    if (defined $filter) {
                        return unless $f =~ s/^\Q$filter\E:://;
                        return if $f eq "";
                    }
                    print "$f\n" unless $seen{$f}++;
                },
                no_chdir => 1,
                follow_fast => 1,
            }, $d);
        }
    ' "$1" 2>/dev/null |
    gawk 'NR < 5000'
}
